The following Verilog code implements a valid/ready asynchronous FIFO with 2**LOG_DEPTH entries of WIDTH bits. It uses two-phase handshaking and synchronizes the data between the source and destination clocks.

```
module cdc_fifo_2phase #(
    parameter WIDTH = 8,
    parameter LOG_DEPTH = 3
)(
    input                  src_rst_ni,
    input                  src_clk_i,
    input  [WIDTH-1:0]     src_data_i,
    input                  src_valid_i,
    output                 src_ready_o,
    input                  dst_rst_ni,
    input                  dst_clk_i,
    output [WIDTH-1:0]     dst_data_o,
    output                 dst_valid_o,
    input                  dst_ready_i
);

    // Internal signals
    reg [WIDTH-1:0] fifo [0:(2**LOG_DEPTH)-1];
    reg [LOG_DEPTH-1:0] head;
    reg [LOG_DEPTH-1:0] tail;
    reg [LOG_DEPTH-1:0] count;
    reg [LOG_DEPTH-1:0] next_head;
    reg [LOG_DEPTH-1:0] next_tail;
    reg [LOG_DEPTH-1:0] next_count;
    reg [LOG_DEPTH-1:0] next_next_count;
    reg [LOG_DEPTH-1:0] next_next_tail;
    reg [LOG_DEPTH-1:0] next_next_next_tail;
    reg [LOG_DEPTH-1:0] next_next_next_next_tail;
